package cn.mcxyd.xiyuanmarry;
import cn.mcxyd.xiyuanmarry.command.*;import cn.mcxyd.xiyuanmarry.config.ConfigurationManager;import cn.mcxyd.xiyuanmarry.gui.*;import cn.mcxyd.xiyuanmarry.listener.CoupleTaskListener;import cn.mcxyd.xiyuanmarry.listener.PlayerLifecycleListener;import cn.mcxyd.xiyuanmarry.message.MessageService;import cn.mcxyd.xiyuanmarry.placeholder.PlaceholderApiHook;import cn.mcxyd.xiyuanmarry.repository.*;import cn.mcxyd.xiyuanmarry.scheduler.UnifiedScheduler;import cn.mcxyd.xiyuanmarry.service.*;import org.bukkit.plugin.java.JavaPlugin;import java.nio.file.*;
/** 只负责插件生命周期、依赖装配和关闭顺序。 */
public final class XiyuanMarryPlugin extends JavaPlugin {
 private ConfigurationManager config;private UnifiedScheduler scheduler;private DatabaseManager database;private IoDispatcher io;private PlayerDirectory directory;private MarriageService marriages;private WeddingService weddings;private DailyTaskService dailyTasks;private SharedOnlineService sharedOnline;private CoupleTaskListener coupleTasks;private GiftService gifts;private RewardService rewards;private ClaimInboxService inbox;private GuiFactory gui;private PartnerTeleportService teleports;private RingService ring;private PlaceholderApiHook placeholders;
@Override public void onEnable(){FoliaSupport.detectOnce();saveDefaultConfig();for(String r:ConfigurationManager.GUI_NAMES.stream().map(x->"gui/"+x+".yml").toList())saveResourceIfMissing(r);for(String r:new String[]{"messages.yml","tasks.yml","rank.yml","rewards.yml","weddings.yml"})saveResourceIfMissing(r);config=new ConfigurationManager(this);config.load();scheduler=new UnifiedScheduler(this);var messages=new MessageService(config);database=new DatabaseManager(config.snapshot().database());io=new IoDispatcher(scheduler,getLogger());directory=new PlayerDirectory(config,scheduler);marriages=new MarriageService(this,config,messages,database,scheduler,io,directory);weddings=new WeddingService(marriages,config,scheduler);marriages.initialize();dailyTasks=new DailyTaskService(marriages,config,scheduler);sharedOnline=new SharedOnlineService(marriages,config,scheduler);coupleTasks=new CoupleTaskListener(marriages,dailyTasks,scheduler);gifts=new GiftService(marriages,scheduler,database);rewards=new RewardService(marriages,config,scheduler,database,io,getLogger());rewards.start();inbox=new ClaimInboxService(marriages,rewards,gifts,scheduler,database,config,messages);teleports=new PartnerTeleportService(marriages,config,database,io,scheduler,getLogger());ring=new RingService(this,marriages,config,directory,scheduler,messages);ring.start();gui=new GuiFactory(config,marriages,weddings,messages,scheduler,dailyTasks);marriages.onReload(()->{dailyTasks.reload();sharedOnline.reload();coupleTasks.reload();gui.reload();weddings.clear();teleports.reload();rewards.reload();ring.reload();if(placeholders!=null)placeholders.reload();});if(getServer().getPluginManager().isPluginEnabled("PlaceholderAPI")){placeholders=new PlaceholderApiHook(this,marriages);placeholders.register();getLogger().info("已注册 PlaceholderAPI 变量扩展。");}MarryCommand player=new MarryCommand(messages,directory,marriages,weddings,gui);MarriageSubcommands.register(player,marriages,weddings,directory,messages,gui,gifts,ring,rewards);player.add(new ClaimSubcommand(inbox,rewards,gifts,directory,messages));player.add(new TeleportSubcommand(teleports,directory,messages));MarryAdminCommand admin=new MarryAdminCommand(messages);AdminSubcommands.register(admin,marriages,directory,messages,ring);gui.commands((p,a)->player.onCommand(p,getCommand("marry"),"marry",a));getCommand("marry").setExecutor(player);getCommand("marry").setTabCompleter(new SubcommandCompleter(player.commands()));getCommand("marryadmin").setExecutor(admin);getCommand("marryadmin").setTabCompleter(new SubcommandCompleter(admin.commands()));getServer().getPluginManager().registerEvents(new cn.mcxyd.xiyuanmarry.listener.PartnerLifecycleListener(teleports),this);getServer().getPluginManager().registerEvents(new GuiListener(gui,scheduler),this);getServer().getPluginManager().registerEvents(new PlayerLifecycleListener(directory,weddings,marriages),this);getServer().getPluginManager().registerEvents(sharedOnline,this);getServer().getPluginManager().registerEvents(coupleTasks,this);getLogger().info("结婚系统 XiyuanMarry 2.8.3 已启用；Folia="+FoliaSupport.isFolia());}
 @Override public void onDisable(){if(placeholders!=null)placeholders.close();if(rewards!=null)rewards.close();if(inbox!=null)inbox.close();if(gifts!=null)gifts.close();if(ring!=null)ring.close();if(teleports!=null)teleports.close();if(sharedOnline!=null)sharedOnline.close();if(coupleTasks!=null)coupleTasks.close();if(gui!=null)gui.close();if(weddings!=null)weddings.clear();if(dailyTasks!=null)dailyTasks.close();if(marriages!=null)marriages.shutdown();if(directory!=null)directory.close();if(io!=null)io.close();if(database!=null)database.close();if(scheduler!=null)scheduler.close();}
 public ConfigurationManager configurationManager(){return config;}public MarriageService marriageService(){return marriages;}
 private void saveResourceIfMissing(String resource){if(!getDataFolder().toPath().resolve(resource).toFile().exists())saveResource(resource,false);}
}










